from __future__ import annotations


def pricing_html() -> str:
    return '''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lucas Pricing</title><style>body{margin:0;background:#05070d;color:#f5f7ff;font:15px system-ui}.w{max-width:1100px;margin:auto;padding:32px}.nav{display:flex;justify-content:space-between;align-items:center}.nav img{height:40px;filter:brightness(0) invert(1)}a{color:inherit;text-decoration:none}.hero{text-align:center;padding:70px 0 35px}.hero h1{font-size:52px}.plans{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.c{background:#0b0f19;border:1px solid #293044;border-radius:18px;padding:26px}.hot{border-color:#6978ff}.p{font-size:34px;font-weight:800}.btn{display:block;text-align:center;background:#5969e9;padding:12px;border-radius:10px;font-weight:700}.exp{margin-top:22px}.mut{color:#9aa4bd}@media(max-width:800px){.plans{grid-template-columns:1fr}}</style><div class="w"><div class="nav"><a href="/"><img src="/assets/lucas-logo-horizontal.png"></a><a href="/dashboard">Dashboard →</a></div><div class="hero"><h1>Simple pricing.</h1><p class="mut">One Lucas account is for one person.</p></div><div class="plans"><div class="c"><h2>Free</h2><div class="p">$0</div><p>1,000 Requests<br>1 Node<br>1 AI account</p><a class="btn" href="/dashboard">Get started</a></div><div class="c"><h2>Pro</h2><div class="p">$9.99/mo</div><p>25,000 Requests<br>3 Nodes<br>1 AI account</p><a class="btn" href="/billing?select=pro">Choose Pro</a></div><div class="c hot"><h2>Pro+</h2><div class="p">$19.99/mo</div><p>100,000 Requests<br>6 Nodes<br>3 AI accounts</p><a class="btn" href="/billing?select=pro_plus">Choose Pro+</a></div></div><div class="c exp"><h2>Expansion Pack · $14.99/mo</h2><p>Pro+ only · +100,000 Requests · +6 Nodes · +1 AI account</p><p class="mut">Only actual Lucas Node tool operations count as Requests.</p></div></div>'''


def billing_html(mode: str = 'billing') -> str:
    banner={'success':'Payment received. Activating your plan…','cancel':'Payment was not completed. Your plan has not changed.'}.get(mode,'')
    return f'''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lucas Billing</title><style>body{{margin:0;background:#f6f7fb;color:#101828;font:14px system-ui}}.w{{max-width:1050px;margin:auto;padding:28px}}.top,.row{{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap}}.top img{{height:40px}}.c{{background:#fff;border:1px solid #e4e7ec;border-radius:14px;padding:20px;margin:15px 0}}.g{{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}}.m{{font-size:28px;font-weight:800}}.mut{{color:#667085}}.btn{{border:0;background:#155eef;color:#fff;padding:11px 14px;border-radius:9px;font-weight:700;cursor:pointer;text-decoration:none}}.sec{{background:#fff;color:#344054;border:1px solid #d0d5dd}}.notice{{padding:12px;background:#eff4ff;border-radius:10px}}.err{{background:#fef3f2;color:#b42318;display:none}}input{{width:70px;padding:9px}}@media(max-width:800px){{.g{{grid-template-columns:1fr}}}}</style><div class="w"><div class="top"><a href="/dashboard"><img src="/assets/lucas-logo-horizontal.png"></a><div class="row"><a class="btn sec" href="/pricing">Pricing</a><a class="btn sec" href="/dashboard">Dashboard</a></div></div>{f'<div class="notice">{banner}</div>' if banner else ''}<div id="err" class="c err"></div><div class="c row"><div><div class="mut">Current plan</div><div id="plan" class="m">Loading…</div><div id="renew" class="mut"></div></div><button id="manage" class="btn sec" onclick="portal()">Manage Billing</button></div><div class="g"><div class="c"><div class="mut">Requests</div><div id="req" class="m">—</div></div><div class="c"><div class="mut">Nodes</div><div id="nodes" class="m">—</div></div><div class="c"><div class="mut">AI accounts</div><div id="ai" class="m">—</div></div></div><h2>Plans</h2><div class="g"><div class="c"><h3>Free · $0</h3><p>1,000 Requests · 1 Node · 1 AI account</p></div><div class="c"><h3>Pro · $9.99/mo</h3><p>25,000 Requests · 3 Nodes · 1 AI account</p><button class="btn" onclick="checkout('pro')">Choose Pro</button></div><div class="c"><h3>Pro+ · $19.99/mo</h3><p>100,000 Requests · 6 Nodes · 3 AI accounts</p><button class="btn" onclick="checkout('pro_plus')">Choose Pro+</button></div></div><div class="c"><h2>Expansion Pack · $14.99/mo</h2><p>Pro+ only · +100,000 Requests · +6 Nodes · +1 AI account</p><div id="exp"></div></div></div><script>async function a(u,o={{}}){{let r=await fetch(u,{{credentials:'include',headers:{{'Content-Type':'application/json'}},...o}}),d={{}};try{{d=await r.json()}}catch{{}}if(r.status===401){{location='/dashboard';return}}if(!r.ok)throw Error(d.error||'Request failed');return d}}function e(x){{err.textContent=x.message;err.style.display='block'}}async function load(){{try{{let s=await a('/api/billing/summary');plan.textContent=s.plan_name+(s.expansion_quantity?' + '+s.expansion_quantity+' Pack(s)':'');renew.textContent=s.renewal_at?'Renews '+new Date(s.renewal_at*1000).toLocaleDateString():'';req.textContent=s.requests_used.toLocaleString()+' / '+s.request_limit.toLocaleString();nodes.textContent=s.nodes_used+' / '+s.node_limit;ai.textContent=s.ai_accounts_used+' / '+s.ai_account_limit;manage.disabled=!s.has_customer;exp.innerHTML=s.can_buy_expansion?'<div class="row"><b>Current: '+s.expansion_quantity+'</b><input id="q" type="number" min="1" value="1"><button class="btn" onclick="pack()">Add Expansion Pack</button></div>':'<button class="btn" onclick="checkout(\'pro_plus\')">Upgrade to Pro+</button>';let x=new URLSearchParams(location.search).get('select');if(x&&s.plan!==x&&!window.once){{window.once=1;checkout(x)}}}}catch(x){{e(x)}}}}async function checkout(p){{try{{let d=await a('/api/billing/checkout',{{method:'POST',body:JSON.stringify({{plan:p}})}});location=d.url}}catch(x){{e(x)}}}}async function pack(){{try{{let d=await a('/api/billing/expansion',{{method:'POST',body:JSON.stringify({{quantity:+q.value||1}})}});location=d.url}}catch(x){{e(x)}}}}async function portal(){{try{{let d=await a('/api/billing/portal',{{method:'POST'}});location=d.url}}catch(x){{e(x)}}}}load();{"setInterval(load,2500);" if mode=='success' else ''}</script>'''
